import subprocess
files=open('/tmp/skfiles.txt').read().split()
def intro(t):
    lines=t.splitlines(); i=None
    for j,l in enumerate(lines):
        if l.startswith('# '): i=j; break
    if i is None: return None
    out=[]
    for l in lines[i+1:]:
        if l.startswith('## ') or l.strip()=='---': break
        out.append(l.strip())
    return '\n'.join(x for x in out if x).strip()
for f in files:
    h=intro(subprocess.run(['git','show','HEAD:'+f],capture_output=True,text=True).stdout)
    n=intro(open(f).read())
    if h!=n:
        print('INTRO-CHANGED',f)
        print(' HEAD:',repr(h))
        print(' NOW :',repr(n))
